INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '3a5abb5e-e742-4d99-94e9-5330c32f7cf4','taxes',$q$take immediate action to lower the tax burden on Maine's WORKING families and our senior citizens by reining in out of control state spending$q$,$q$take immediate action to lower the tax burden on Maine's WORKING families and our senior citizens by reining in out of control state spending$q$,'https://www.bangordailynews.com/profile/lucien-jb-daigle/','Bangor Daily News',true,$q$From Daigle's Oct. 2024 BDN candidate questionnaire; verbatim, no de-identification edits were needed since the quote names no person, party, or office. He explicitly pairs tax cuts with reduced state spending, matching the broad tax-cut-plus-smaller-government stance.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='3a5abb5e-e742-4d99-94e9-5330c32f7cf4' AND topic_key='taxes' AND quote_text=$q$take immediate action to lower the tax burden on Maine's WORKING families and our senior citizens by reining in out of control state spending$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '3a5abb5e-e742-4d99-94e9-5330c32f7cf4','housing',$q$Regulations, permits, inspections, and fees for construction of homes and housing units take too much time and unnecessarily increase the cost of construction.$q$,$q$Regulations, permits, inspections, and fees for construction of homes and housing units take too much time and unnecessarily increase the cost of construction.$q$,'https://www.bangordailynews.com/profile/lucien-jb-daigle/','Bangor Daily News',true,$q$From the same Oct. 2024 BDN questionnaire; verbatim, no de-identification edits needed (no name/party/office appears in the text). This is his own stated diagnosis and remedy for housing costs, matching the deregulation-focused stance.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='3a5abb5e-e742-4d99-94e9-5330c32f7cf4' AND topic_key='housing' AND quote_text=$q$Regulations, permits, inspections, and fees for construction of homes and housing units take too much time and unnecessarily increase the cost of construction.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'ac47488f-8044-4f39-a33e-0e3ff1c450fb','local-immigration',$q$This bill is a dangerous attempt to interfere with local law enforcement and make their jobs even more difficult. It also jeopardizes access to important funding that is vital to protecting Maine citizens in a dangerous world.$q$,$q$This bill is a dangerous attempt to interfere with local law enforcement and make their jobs even more difficult. It also jeopardizes access to important funding that is vital to protecting Maine citizens in a dangerous world.$q$,'https://mainehousegop.org/newsroom/republicans-urge-governor-to-veto-bill-that-interferes-with-local-law-enforcement/','Maine House Republicans',true,$q$Verbatim quote from a Maine House Republican Office news release (6/23/2025) in which this representative, who circulated the letter, argues against a bill limiting local police cooperation with federal immigration detainers. No edits made -- the quote contains no name, party label, or office claim, so it was already safe to show blind.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='ac47488f-8044-4f39-a33e-0e3ff1c450fb' AND topic_key='local-immigration' AND quote_text=$q$This bill is a dangerous attempt to interfere with local law enforcement and make their jobs even more difficult. It also jeopardizes access to important funding that is vital to protecting Maine citizens in a dangerous world.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'f4c74fad-1aa0-46d3-98ea-f377f4e639ba','immigration',$q$General assistance was designed to meet the basic needs of community residents, not accommodate large numbers of people shipped here from the southern border.$q$,$q$General assistance was designed to meet the basic needs of community residents, not accommodate large numbers of people shipped here from the southern border.$q$,'https://mainehousegop.org/newsroom/maines-housing-situation-changed-drastically-in-5-years/','Maine House Republicans',true,$q$Verbatim quote from Poirier's June 2024 Maine House Republicans op-ed on housing costs and immigration; no edits needed for de-identification since the quote contains no name, party, office, or other self-identifying language.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='f4c74fad-1aa0-46d3-98ea-f377f4e639ba' AND topic_key='immigration' AND quote_text=$q$General assistance was designed to meet the basic needs of community residents, not accommodate large numbers of people shipped here from the southern border.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'dc6a829a-5501-4f63-9d34-fa5210b80fc2','climate-change',$q$We must start by directing the department to prioritize lowering energy costs for Maine ratepayers and increase transparency in our electricity bills.$q$,$q$We must start by directing the department to prioritize lowering energy costs for Maine ratepayers and increase transparency in our electricity bills.$q$,'https://mainehousegop.org/member_news_item/we-need-solutions-that-lower-energy-costs/','Maine House Republicans',true,$q$Verbatim quote from Ducharme's November 2023 Maine House Republicans op-ed on electricity costs; no edits needed for de-identification since the quote contains no name, party, office, or other self-identifying language.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='dc6a829a-5501-4f63-9d34-fa5210b80fc2' AND topic_key='climate-change' AND quote_text=$q$We must start by directing the department to prioritize lowering energy costs for Maine ratepayers and increase transparency in our electricity bills.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'dc6a829a-5501-4f63-9d34-fa5210b80fc2','taxes',$q$We MUST stop taking more money from Mainers to run government than we need.$q$,$q$We MUST stop taking more money from Mainers to run government than we need.$q$,'https://mainehousegop.org/member_news_item/tax-relief-must-be-part-of-the-conversation/','Maine House Republicans',true,$q$Verbatim quote from Ducharme's April 2023 Maine House Republicans op-ed on tax relief and the balanced budget amendment; no edits needed for de-identification since the quote contains no name, party, office, or other self-identifying language.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='dc6a829a-5501-4f63-9d34-fa5210b80fc2' AND topic_key='taxes' AND quote_text=$q$We MUST stop taking more money from Mainers to run government than we need.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '80747346-be87-4d1b-9bf6-9ee80356ba7f','trans-athletes',$q$Regardless of religious belief or even political affiliation, the majority of Mainers and Americans clearly see that allowing males to compete in girls' sports is unfair, discriminatory, and denies biological reality.$q$,$q$Regardless of religious belief or even political affiliation, the majority of Mainers and Americans clearly see that allowing males to compete in girls' sports is unfair, discriminatory, and denies biological reality.$q$,'https://www.themainewire.com/2025/07/fringe-clergy-now-joins-fight-against-common-sense-led-by-reps-caruso-and-libby/','The Maine Wire',true,$q$Verbatim quote reported by the Maine Wire (July 2025) about Caruso's own bill (LD 868) restricting transgender athletes' eligibility in girls' sports; no edits needed for de-identification since the quote contains no name, party, office, or other self-identifying language.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='80747346-be87-4d1b-9bf6-9ee80356ba7f' AND topic_key='trans-athletes' AND quote_text=$q$Regardless of religious belief or even political affiliation, the majority of Mainers and Americans clearly see that allowing males to compete in girls' sports is unfair, discriminatory, and denies biological reality.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'b08821e4-7a92-498c-97f2-13138777e8ae','immigration',$q$Republicans favor legal immigration that offers a way to employment.$q$,$q$[Some] favor legal immigration that offers a way to employment.$q$,'https://mainehousegop.org/member_news_item/republicans-uncover-shocking-cost-of-our-open-border-policy/','Maine House Republicans',true,$q$Verbatim line from Schmersal-Burgess's Feb. 2024 statement on asylum-seeker housing spending (mainehousegop.org); shows support for legal immigration paired with limiting services/spending for others, matching the 'limit public services to legal status' language. Only edit: 'Republicans' replaced with '[Some]' to remove the party tell.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='b08821e4-7a92-498c-97f2-13138777e8ae' AND topic_key='immigration' AND quote_text=$q$Republicans favor legal immigration that offers a way to employment.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'a37ec3f9-faa6-4c06-8856-92fa618a28ad','immigration',$q$It will only fuel more migration from people seeking over-the-top public assistance benefits.$q$,$q$It will only fuel more migration from people seeking over-the-top public assistance benefits.$q$,'https://mainehousegop.org/newsroom/maine-is-making-international-news/','Maine House Republicans',true,$q$Verbatim line from Henderson's March 2024 Weekly Republican Radio Address on asylum-seeker housing spending (mainehousegop.org); directly states that generous public benefits attract more migration, matching the 'limit public services to legal status' language. No edits needed -- contains no name, party, or office tell.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='a37ec3f9-faa6-4c06-8856-92fa618a28ad' AND topic_key='immigration' AND quote_text=$q$It will only fuel more migration from people seeking over-the-top public assistance benefits.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'c6b1a2ed-c20a-44ef-b9b0-58de24c5f837','climate-change',$q$We need to restore balance, fairness, and affordability to our energy system. Mainers deserve reliable and reasonably priced power—not policies that drive costs through the roof.$q$,$q$We need to restore balance, fairness, and affordability to our energy system. Mainers deserve reliable and reasonably priced power—not policies that drive costs through the roof.$q$,'https://mainehousegop.org/newsroom/maine-ratepayers-deserve-relief-from-skyrocketing-electricity-costs/','Maine House Republicans',true,$q$Verbatim from Wood's Aug 22, 2025 Weekly Republican Radio Address on mainehousegop.org, arguing against renewable-energy mandates and for market-based energy policy — directly supports his climate-change=4 stance. No de-identification edits needed; the quote contains no name, party, or office markers, only the general demographic term 'Mainers.'$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='c6b1a2ed-c20a-44ef-b9b0-58de24c5f837' AND topic_key='climate-change' AND quote_text=$q$We need to restore balance, fairness, and affordability to our energy system. Mainers deserve reliable and reasonably priced power—not policies that drive costs through the roof.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'c1b625df-6943-49e8-a0a7-c603c4718ac1','trans-athletes',$q$Girls' sports has come a long way and I think we have a responsibility to protect girls' sports, to protect Maine girls, and to ensure they have a level playing field.$q$,$q$Girls' sports has come a long way and I think we have a responsibility to protect girls' sports, to protect Maine girls, and to ensure they have a level playing field.$q$,'https://www.newsweek.com/transgender-athlete-win-maine-sparks-backlash-2033960','Newsweek',true,$q$Verbatim from a February 19/20 2025 WMTW article quoting her directly about the pole-vault controversy that led to her House censure; no identifying edits were needed since the quote contains no name/party/office markers beyond the state name Maine which is not considered identifying.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='c1b625df-6943-49e8-a0a7-c603c4718ac1' AND topic_key='trans-athletes' AND quote_text=$q$Girls' sports has come a long way and I think we have a responsibility to protect girls' sports, to protect Maine girls, and to ensure they have a level playing field.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'c1b625df-6943-49e8-a0a7-c603c4718ac1','school-vouchers',$q$School choice puts education funds to work wherever they best serve the individual student, rather than mandating that taxpayer funds can only be used at government-run schools.$q$,$q$School choice puts education funds to work wherever they best serve the individual student, rather than mandating that taxpayer funds can only be used at government-run schools.$q$,'https://mainehousegop.org/member_news_item/rep-laurel-libby-introduces-school-choice-legislation-to-benefit-students/','Maine House Republicans',true,$q$Verbatim from a mainehousegop.org press release announcing her Educational Opportunity Account bill during National School Choice Week; no edits needed as the quote contains no name/party/office markers.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='c1b625df-6943-49e8-a0a7-c603c4718ac1' AND topic_key='school-vouchers' AND quote_text=$q$School choice puts education funds to work wherever they best serve the individual student, rather than mandating that taxpayer funds can only be used at government-run schools.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '98ea2b14-dfe7-4a4c-a755-a124a77a24eb','voting-rights',$q$Their opposition is puzzling, since identification cards can be provided by the government to the tiny number of people who do not have identification.$q$,$q$Their opposition is puzzling, since identification cards can be provided by the government to the tiny number of people who do not have identification.$q$,'https://mainehousegop.org/newsroom/there-is-bipartisan-support-for-voter-i-d/','Maine House Republicans',true,$q$Verbatim from his own mainehousegop.org weekly radio address transcript on voter ID; no edits needed as the sentence names no specific party/person.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='98ea2b14-dfe7-4a4c-a755-a124a77a24eb' AND topic_key='voting-rights' AND quote_text=$q$Their opposition is puzzling, since identification cards can be provided by the government to the tiny number of people who do not have identification.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '04a1f435-1a5c-42db-9efd-410e65652f40','local-immigration',$q$No one is required to open their door without a warrant signed by a judge.$q$,$q$No one is required to open their door without a warrant signed by a judge.$q$,'https://www.maine.gov/housedems/news/statement-rep-mana-abdi-potential-federal-law-enforcement-operations-lewiston','Maine House Democrats',true,$q$From Rep. Abdi's Jan 15, 2026 public statement on potential federal immigration-enforcement activity in Lewiston; verbatim, only trimmed the trailing ellipsis from the source sentence. It shows she frames local residents' rights as bounded by a judicial warrant requirement, aligning with her votes to bar local police from civil immigration-enforcement cooperation absent a court order.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='04a1f435-1a5c-42db-9efd-410e65652f40' AND topic_key='local-immigration' AND quote_text=$q$No one is required to open their door without a warrant signed by a judge.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '7560948b-f1f1-422c-be0c-f92865c100f9','taxes',$q$Rural municipal budgets are overburdened by excessive taxes and unfunded mandates. This has placed our communities in jeopardy as the costs of maintaining basic essential services has become unsustainable. This tax on emergency services is unreasonable and dangerous.$q$,$q$Rural municipal budgets are overburdened by excessive taxes and unfunded mandates. This has placed our communities in jeopardy as the costs of maintaining basic essential services has become unsustainable. This tax on emergency services is unreasonable and dangerous.$q$,'https://mainehousegop.org/member_news_item/senior-house-republicans-blast-latest-mills-tax-on-medicines-ambulances/','Maine House Republicans',true,$q$Verbatim quote from a Jan. 15, 2025 House Republican press release opposing a proposed state tax on ambulance and prescription services — a direct, forward-looking statement against raising taxes, supporting the low-tax stance. No words changed; nothing identifying (name/party/office) appeared in the quoted sentences, so no bracket edits were needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='7560948b-f1f1-422c-be0c-f92865c100f9' AND topic_key='taxes' AND quote_text=$q$Rural municipal budgets are overburdened by excessive taxes and unfunded mandates. This has placed our communities in jeopardy as the costs of maintaining basic essential services has become unsustainable. This tax on emergency services is unreasonable and dangerous.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '993299cd-a7b5-4246-a8f2-57e6eb7df1b9','voting-rights',$q$Maine people are being asked to weigh in on whether to adopt the same commonsense Voter ID standards used in 36 other states.$q$,$q$Maine people are being asked to weigh in on whether to adopt the same commonsense Voter ID standards used in 36 other states.$q$,'https://mainehousegop.org/newsroom/maine-election-security-and-integrity-called-into-question-again/','Maine House Republicans',true,$q$Verbatim clause from an Oct. 1, 2025 House Republican press release urging adoption of statewide photo Voter ID standards, directly supporting the voter-ID chair of the voting-rights scale. Trimmed the surrounding sentences about a ballot-shipping incident and a closing call for accountability; no words within the kept clause were altered. De-identified version keeps the bare state reference (not personally identifying) and drops no other content, so no bracket substitutions were needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='993299cd-a7b5-4246-a8f2-57e6eb7df1b9' AND topic_key='voting-rights' AND quote_text=$q$Maine people are being asked to weigh in on whether to adopt the same commonsense Voter ID standards used in 36 other states.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '8d45a199-5054-417f-b9a9-3874e113c5f4','healthcare',$q$Mainers who are facing a difficult health situation deserve to have the most effective and least harmful treatment for their specific version of a disease.$q$,$q$Mainers who are facing a difficult health situation deserve to have the most effective and least harmful treatment for their specific version of a disease.$q$,'https://www.maine.gov/housedems/news/house-advances-bipartisan-zager-bill-require-health-insurance-coverage-biomarker-testing','Maine House Democrats',true,$q$Verbatim quote from the 4/11/2024 Maine House Democrats press release on his biomarker-testing insurance-coverage bill. No de-identification edits needed -- contains no name, party, or office self-reference.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='8d45a199-5054-417f-b9a9-3874e113c5f4' AND topic_key='healthcare' AND quote_text=$q$Mainers who are facing a difficult health situation deserve to have the most effective and least harmful treatment for their specific version of a disease.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'd7ad5924-0e8a-4d11-93e3-56e1db5dd019','voting-rights',$q$This bill would improve voter access by giving working Mainers an opportunity to vote on the weekend.$q$,$q$This bill would improve voter access by giving working Mainers an opportunity to vote on the weekend.$q$,'https://www.maine.gov/housedems/news/skold-introduces-bill-increase-voting-access-mainers','Maine House Democrats',true,$q$Verbatim from his March 2023 press release announcing his Saturday absentee-voting bill. No edits needed -- contains no name, party, or office self-reference.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='d7ad5924-0e8a-4d11-93e3-56e1db5dd019' AND topic_key='voting-rights' AND quote_text=$q$This bill would improve voter access by giving working Mainers an opportunity to vote on the weekend.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'd7ad5924-0e8a-4d11-93e3-56e1db5dd019','judicial-access-to-justice',$q$Financial resources should not be a barrier to accessing justice.$q$,$q$Financial resources should not be a barrier to accessing justice.$q$,'https://www.maine.gov/housedems/news/skold-introduces-bill-increase-access-legal-representation-lower-income-mainers','Maine House Democrats',true,$q$Verbatim from his April 2023 press release introducing a fee-shifting bill for low-income civil litigants. No edits needed -- contains no name, party, or office self-reference.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='d7ad5924-0e8a-4d11-93e3-56e1db5dd019' AND topic_key='judicial-access-to-justice' AND quote_text=$q$Financial resources should not be a barrier to accessing justice.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '2e737f21-8570-4ad2-8d68-9b0678ac2c3f','local-immigration',$q$Local police taking part in enforcing federal immigration law damages their relationship with immigrant communities, erodes public trust and makes us all less safe, whether we are immigrants or not.$q$,$q$Local police taking part in enforcing federal immigration law damages their relationship with immigrant communities, erodes public trust and makes us all less safe, whether we are immigrants or not.$q$,'https://www.wabi.tv/2025/12/15/gov-mills-will-allow-bill-that-limits-police-cooperation-with-ice-become-law/','WABI-TV',true,$q$Verbatim clause from her December 2025 statement on LD 1971's enactment, trimmed to the forward policy-rationale sentence. No substitutions needed -- contains no name, party, or office self-reference.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='2e737f21-8570-4ad2-8d68-9b0678ac2c3f' AND topic_key='local-immigration' AND quote_text=$q$Local police taking part in enforcing federal immigration law damages their relationship with immigrant communities, erodes public trust and makes us all less safe, whether we are immigrants or not.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '2e737f21-8570-4ad2-8d68-9b0678ac2c3f','immigration',$q$By establishing a central hub of information and resources for New Mainers, I believe this office will help usher in a new era of opportunity for all of Maine.$q$,$q$By establishing a central hub of information and resources for New Mainers, I believe this office will help usher in a new era of opportunity for all of Maine.$q$,'https://www.maine.gov/housedems/news/dhalac-proposal-would-create-office-new-americans-maine-state-government','Maine House Democrats',true,$q$Verbatim from her January 2024 press release proposing a state Office of New Americans. No edits needed -- contains no name, party, or office self-reference.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='2e737f21-8570-4ad2-8d68-9b0678ac2c3f' AND topic_key='immigration' AND quote_text=$q$By establishing a central hub of information and resources for New Mainers, I believe this office will help usher in a new era of opportunity for all of Maine.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'bb7a224e-a0af-4bd8-a2a9-d70c35e1eefc','housing',$q$All of the upfront fees that come with renting an apartment make housing even more unaffordable for too many Mainers.$q$,$q$All of the upfront fees that come with renting an apartment make housing even more unaffordable for too many Mainers.$q$,'https://www.maine.gov/housedems/news/kessler-introduces-bill-limit-upfront-fees-imposed-renters','Maine House Democrats',true,$q$Verbatim from his May 2023 press release introducing a bill to limit upfront renter fees. No edits needed -- contains no name, party, or office self-reference.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='bb7a224e-a0af-4bd8-a2a9-d70c35e1eefc' AND topic_key='housing' AND quote_text=$q$All of the upfront fees that come with renting an apartment make housing even more unaffordable for too many Mainers.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '835e9c91-f373-4c9d-af75-6a5dd68539ec','tariffs',$q$Maintaining a healthy relationship with Maine's trading partners is crucial to building a strong and sustainable economy, especially now that the federal government is putting our best interests at risk by starting a series of trade wars with many of our allies, like Canada.$q$,$q$Maintaining a healthy relationship with [our state]'s trading partners is crucial to building a strong and sustainable economy, especially now that the federal government is putting our best interests at risk by starting a series of trade wars with many of our allies, like Canada.$q$,'https://www.maine.gov/housedems/news/rielly-named-house-chair-citizen-trade-policy-commission','Maine House Democrats',true,$q$Verbatim quote from a 4/29/2025 Maine House Democrats press release announcing Rielly's Citizen Trade Policy Commission chairmanship; it directly criticizes federal tariff/trade-war policy and favors maintaining open trade relationships, aligning with the tariffs scale's low-tariff chairs. De-identification: substituted the state name "Maine's" with the generic "[our state]'s" since the surrounding announcement context (naming his commission chairmanship) makes "Maine" a closer identity tell than in a standalone quote; no other edits needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='835e9c91-f373-4c9d-af75-6a5dd68539ec' AND topic_key='tariffs' AND quote_text=$q$Maintaining a healthy relationship with Maine's trading partners is crucial to building a strong and sustainable economy, especially now that the federal government is putting our best interests at risk by starting a series of trade wars with many of our allies, like Canada.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'd921e2be-d1e4-456a-915c-a4b3780dd633','healthcare',$q$Increasingly, communities in rural parts of the state are struggling to receive the emergency health care they need.$q$,$q$Increasingly, communities in rural parts of the state are struggling to receive the emergency health care they need.$q$,'https://www.maine.gov/housedems/news/house-advances-salisbury-bill-support-access-emergency-health-care','Maine House Democrats',true,$q$communities in rural parts of the state are struggling to receive the emergency health care they need$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='d921e2be-d1e4-456a-915c-a4b3780dd633' AND topic_key='healthcare' AND quote_text=$q$Increasingly, communities in rural parts of the state are struggling to receive the emergency health care they need.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '185b5de5-50a4-4a5b-9cef-f64f0ab1cb4c','healthcare',$q$Dental disease is the most common chronic condition affecting Maine children, and if left untreated, it can harm physical health, school performance, self esteem and more.$q$,$q$Dental disease is the most common chronic condition affecting Maine children, and if left untreated, it can harm physical health, school performance, self esteem and more.$q$,'https://www.maine.gov/housedems/news/gramlich-bill-improve-childrens-oral-health-now-law','Maine House Democrats',true,$q$Verbatim from her own housedems press release on LD 1746 (children's oral health); no identifying language present so no edits were needed. Shows her prioritizing expanded public health programs for children, supporting a mixed public/private coverage approach.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='185b5de5-50a4-4a5b-9cef-f64f0ab1cb4c' AND topic_key='healthcare' AND quote_text=$q$Dental disease is the most common chronic condition affecting Maine children, and if left untreated, it can harm physical health, school performance, self esteem and more.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '185b5de5-50a4-4a5b-9cef-f64f0ab1cb4c','deportation',$q$This incident highlights the importance and necessity of reliable federal systems to support the lawful employment of noncitizen residents in community-serving roles.$q$,$q$This incident highlights the importance and necessity of reliable federal systems to support the lawful employment of noncitizen residents in community-serving roles.$q$,'https://www.maine.gov/housedems/news/statement-rep-lori-k-gramlich-assistant-house-majority-leader-ice-detention-old-orchard-beach','Maine House Democrats',true,$q$Verbatim from her own July 30, 2025 official statement on the ICE detention of a local reserve police officer; no identifying language present so no edits were needed. Shows her calling for fair, accountable treatment of lawfully-working noncitizen residents rather than aggressive removal.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='185b5de5-50a4-4a5b-9cef-f64f0ab1cb4c' AND topic_key='deportation' AND quote_text=$q$This incident highlights the importance and necessity of reliable federal systems to support the lawful employment of noncitizen residents in community-serving roles.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '6465949e-7832-40cb-962f-839ebecf32ce','housing',$q$An energy-efficient home should be accessible to all Mainers, not just those who are wealthy enough to keep up with home repairs.$q$,$q$An energy-efficient home should be accessible to all Mainers, not just those who are wealthy enough to keep up with home repairs.$q$,'https://www.maine.gov/housedems/news/malon-introduces-measure-help-more-families-create-energy-efficient-homes','Maine House Democrats',true,$q$Verbatim from his own housedems press release introducing LD 996 (home weatherization fund for low/fixed-income Mainers); no identifying language present so no edits were needed. Supports targeted public subsidies to make housing/home repair affordable for lower-income residents.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='6465949e-7832-40cb-962f-839ebecf32ce' AND topic_key='housing' AND quote_text=$q$An energy-efficient home should be accessible to all Mainers, not just those who are wealthy enough to keep up with home repairs.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '6793f0eb-ddaa-4c72-ac99-70876295279a','housing',$q$Converting vacant schools into housing is a common sense approach to creating affordable and attainable housing.$q$,$q$Converting vacant schools into housing is a common sense approach to creating affordable and attainable housing.$q$,'https://www.maine.gov/housedems/news/committee-advances-gere-legislation-create-new-housing-maine','Maine House Democrats',true,$q$From Gere's own March 2026 statement on her LD 2164 school-to-housing conversion bill, verbatim, no edits needed for de-identification; shows she backs direct public funding to expand housing supply.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='6793f0eb-ddaa-4c72-ac99-70876295279a' AND topic_key='housing' AND quote_text=$q$Converting vacant schools into housing is a common sense approach to creating affordable and attainable housing.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '18b11787-c861-4996-aba5-3b863ea33b1d','climate-change',$q$doing all we can at the state level to address the immediate threat of climate change through strategies to curb future carbon emissions$q$,$q$doing all we can at the state level to address the immediate threat of climate change through strategies to curb future carbon emissions$q$,'https://ballotpedia.org/Daniel_Sayre','Ballotpedia Candidate Connection',true,$q$From Sayre's own 2022 Ballotpedia Candidate Connection survey answer, verbatim; shows an incremental clean-energy stance matching his LD1870/LD2037 floor votes. No de-identification edits needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='18b11787-c861-4996-aba5-3b863ea33b1d' AND topic_key='climate-change' AND quote_text=$q$doing all we can at the state level to address the immediate threat of climate change through strategies to curb future carbon emissions$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '18b11787-c861-4996-aba5-3b863ea33b1d','housing',$q$removing some restrictions on Accessory Dwelling Units, controlling the proliferation of short-term rentals, and working with builders and developers to find ways to make new home development more cost-efficient$q$,$q$removing some restrictions on Accessory Dwelling Units, controlling the proliferation of short-term rentals, and working with builders and developers to find ways to make new home development more cost-efficient$q$,'https://ballotpedia.org/Daniel_Sayre','Ballotpedia Candidate Connection',true,$q$From Sayre's own 2022 Ballotpedia Candidate Connection housing-policy answer, verbatim; shows a targeted deregulation/buyer-assistance approach rather than direct public housing or rent caps. No de-identification edits needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='18b11787-c861-4996-aba5-3b863ea33b1d' AND topic_key='housing' AND quote_text=$q$removing some restrictions on Accessory Dwelling Units, controlling the proliferation of short-term rentals, and working with builders and developers to find ways to make new home development more cost-efficient$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '18b11787-c861-4996-aba5-3b863ea33b1d','civil-rights',$q$ensuring that access to education, economic opportunity, and all civil rights are not infringed based on a person's racial, ethnic, religious, gender or sexual identity$q$,$q$ensuring that access to education, economic opportunity, and all civil rights are not infringed based on a person's racial, ethnic, religious, gender or sexual identity$q$,'https://ballotpedia.org/Daniel_Sayre','Ballotpedia Candidate Connection',true,$q$From Sayre's own 2022 Ballotpedia Candidate Connection survey, verbatim; a general nondiscrimination commitment naming race among other categories. No de-identification edits needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='18b11787-c861-4996-aba5-3b863ea33b1d' AND topic_key='civil-rights' AND quote_text=$q$ensuring that access to education, economic opportunity, and all civil rights are not infringed based on a person's racial, ethnic, religious, gender or sexual identity$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '18b11787-c861-4996-aba5-3b863ea33b1d','redistricting',$q$Maine puts redistricting in the hands of an evenly balanced bi-partisan commission and that's the right way to do it.$q$,$q$Maine puts redistricting in the hands of an evenly balanced bi-partisan commission and that's the right way to do it.$q$,'https://ballotpedia.org/Daniel_Sayre','Ballotpedia Candidate Connection',true,$q$From Sayre's own 2022 Ballotpedia Candidate Connection survey, verbatim; a direct endorsement of Maine's bipartisan redistricting-commission model. No de-identification edits needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='18b11787-c861-4996-aba5-3b863ea33b1d' AND topic_key='redistricting' AND quote_text=$q$Maine puts redistricting in the hands of an evenly balanced bi-partisan commission and that's the right way to do it.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '18b11787-c861-4996-aba5-3b863ea33b1d','tariffs',$q$After listening to testimony, it's obvious that President Trump's tariff policies are hurting Maine people and businesses.$q$,$q$After listening to testimony, it's obvious that President Trump's tariff policies are hurting Maine people and businesses.$q$,'https://www.maine.gov/housedems/news/state-commission-hears-about-impacts-tariffs-maine','Maine House Democrats',true,$q$After listening to testimony$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='18b11787-c861-4996-aba5-3b863ea33b1d' AND topic_key='tariffs' AND quote_text=$q$After listening to testimony, it's obvious that President Trump's tariff policies are hurting Maine people and businesses.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '289e568d-a9e5-4e9d-9626-3b11891cd12b','data-centers',$q$these data centers will have a devastating effect on our civil liberties and cause massive job losses in Maine as AI is poised to wipe out most clerical positions and replace people with robotics across manufacturing$q$,$q$these data centers will have a devastating effect on our civil liberties and cause massive job losses in Maine as AI is poised to wipe out most clerical positions and replace people with robotics across manufacturing$q$,'https://mainehousegop.org/member_news_item/common-sense/','Maine House Republicans',true,$q$From Eder's own mainehousegop.org Weekly Republican Radio Address ("Common Sense"), verbatim; explains his vote for an AI data-center construction moratorium. No de-identification edits needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='289e568d-a9e5-4e9d-9626-3b11891cd12b' AND topic_key='data-centers' AND quote_text=$q$these data centers will have a devastating effect on our civil liberties and cause massive job losses in Maine as AI is poised to wipe out most clerical positions and replace people with robotics across manufacturing$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '289e568d-a9e5-4e9d-9626-3b11891cd12b','civil-rights',$q$Diversity, Equity, and Inclusion, or DEI, is a form of discrimination against students on the basis of race.$q$,$q$Diversity, Equity, and Inclusion, or DEI, is a form of discrimination against students on the basis of race.$q$,'https://mainehousegop.org/newsroom/maine-schools-warned-against-discriminating-on-the-basis-of-race-color-or-national-origin/','Maine House Republicans',true,$q$From Eder's own Feb. 2025 mainehousegop.org Weekly Republican Address, verbatim; a direct statement opposing DEI/race-conscious programs as discriminatory. No de-identification edits needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='289e568d-a9e5-4e9d-9626-3b11891cd12b' AND topic_key='civil-rights' AND quote_text=$q$Diversity, Equity, and Inclusion, or DEI, is a form of discrimination against students on the basis of race.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'ebd1c39c-73cc-4346-a7f3-55a4274045a3','taxes',$q$state government is taking too much money from taxpayers at a time when they can least afford it$q$,$q$state government is taking too much money from taxpayers at a time when they can least afford it$q$,'https://mainehousegop.org/member_news_item/government-takes-too-return-money-to-mainers-hurt-by-rising-prices/','Maine House Republicans',true,$q$From Carlow's own mainehousegop.org Weekly Republican Radio Address on a state revenue surplus, verbatim; supports a tax-cutting position consistent with his LD229 Nay vote. No de-identification edits needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='ebd1c39c-73cc-4346-a7f3-55a4274045a3' AND topic_key='taxes' AND quote_text=$q$state government is taking too much money from taxpayers at a time when they can least afford it$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'c0a1a251-feb5-4ec7-bbbf-7cf7d3da31a6','taxes',$q$lowering the income tax burden on Maine people, especially those struggling to pay bills in this economy$q$,$q$lowering the income tax burden on Maine people, especially those struggling to pay bills in this economy$q$,'https://mainehousegop.org/newsroom/time-seems-ripe-for-bipartisan-action-on-income-tax-cuts-in-maine/','Maine House Republicans',true,$q$From Blier's own April 2023 mainehousegop.org Weekly Republican Radio Address, verbatim; a direct call for broad income-tax cuts. No de-identification edits needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='c0a1a251-feb5-4ec7-bbbf-7cf7d3da31a6' AND topic_key='taxes' AND quote_text=$q$lowering the income tax burden on Maine people, especially those struggling to pay bills in this economy$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '2b061c70-8654-4725-98cd-373a13badf86','taxes',$q$We need to give tax relief to our low and middle income earners, those hit hardest by historic price increases for everyday items.$q$,$q$We need to give tax relief to our low and middle income earners, those hit hardest by historic price increases for everyday items.$q$,'https://mainehousegop.org/member_news_item/bill-to-provide-tax-relief-to-lower-and-middle-income-earners-to-have-public-hearing/','Maine House Republicans',true,$q$Verbatim from Lanigan's March 27, 2023 press release announcing his own bill (LD 533) to exempt overtime pay from state income tax; shows forward-looking reasoning for cutting taxes on working Mainers, consistent with his LD 229 vote against raising upper-bracket rates (taxes chair 4). No de-identification edits needed -- the quote contains no name, party, or office reference.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='2b061c70-8654-4725-98cd-373a13badf86' AND topic_key='taxes' AND quote_text=$q$We need to give tax relief to our low and middle income earners, those hit hardest by historic price increases for everyday items.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'ec48f5a7-1efd-4942-8e13-65584102df0d','homelessness',$q$By ensuring this funding, we can prevent closures that would otherwise devastate communities throughout Maine.$q$,$q$By ensuring this funding, we can prevent closures that would otherwise devastate communities throughout Maine.$q$,'https://www.maine.gov/housedems/news/mastraccio-introduces-bill-support-maine-homeless-shelters','Maine House Democrats',true,$q$Verbatim from Mastraccio's January 23, 2024 press release introducing her bill (LD 2136) to make permanent a $10 million increase to Maine's homeless-shelter operating subsidy; shows forward-looking reasoning for sustained shelter-funding investment, aligned with homelessness chair 2. No de-identification edits needed -- the quote contains no name, party, or office reference.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='ec48f5a7-1efd-4942-8e13-65584102df0d' AND topic_key='homelessness' AND quote_text=$q$By ensuring this funding, we can prevent closures that would otherwise devastate communities throughout Maine.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'b13ec962-0772-4fdd-8399-59c3bc7fa19a','trans-athletes',$q$No boys in Girls sports or locker rooms or restrooms$q$,$q$No boys in Girls sports or locker rooms or restrooms$q$,'https://ballotpedia.org/Thomas_Lavigne','Ballotpedia Candidate Connection',true,$q$Verbatim from Rep. Lavigne's 2026 Ballotpedia Candidate Connection survey (his stated top-three priorities). No de-identifying edits were needed since the quote contains no name, party, or office reference.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='b13ec962-0772-4fdd-8399-59c3bc7fa19a' AND topic_key='trans-athletes' AND quote_text=$q$No boys in Girls sports or locker rooms or restrooms$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'b13ec962-0772-4fdd-8399-59c3bc7fa19a','taxes',$q$Restore the cap on municipality taxes to 2% annually.$q$,$q$Restore the cap on municipality taxes to 2% annually.$q$,'https://ballotpedia.org/Thomas_Lavigne','Ballotpedia Candidate Connection',true,$q$Verbatim from Rep. Lavigne's 2026 Ballotpedia Candidate Connection survey answer on his district's most significant issue. No de-identifying edits needed -- contains no name, party, or office reference.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='b13ec962-0772-4fdd-8399-59c3bc7fa19a' AND topic_key='taxes' AND quote_text=$q$Restore the cap on municipality taxes to 2% annually.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '7ebe7923-3a6a-464e-9646-4e688459f614','healthcare',$q$With costs climbing and health care growing harder to find in rural communities, the Speaker's proposal lands at exactly the right moment. I'm thrilled a majority of the committee voted to push this measure forward.$q$,$q$With costs climbing and health care growing harder to find in rural communities, [this] proposal lands at exactly the right moment. I'm thrilled a majority of the committee voted to push this measure forward.$q$,'https://mainemorningstar.com/2026/03/13/legislature-poised-to-vote-on-massive-bills-to-offset-federal-cuts-to-snap-health-care/','Maine Morning Star',true,$q$Verbatim quote from Maine Morning Star (3/13/2026) about LD 2208's committee passage; she later voted to enact the same bill on the House floor (Roll Call #738). De-identified by replacing 'the Speaker's' with '[this]' to remove the reference to legislative leadership that could hint at her chamber role.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='7ebe7923-3a6a-464e-9646-4e688459f614' AND topic_key='healthcare' AND quote_text=$q$With costs climbing and health care growing harder to find in rural communities, the Speaker's proposal lands at exactly the right moment. I'm thrilled a majority of the committee voted to push this measure forward.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '1f6fb9ae-a29b-4174-baf3-1116371c4955','climate-change',$q$The fact that unelected bureaucrats have the power to impose draconian measures on us is scary.$q$,$q$The fact that unelected bureaucrats have the power to impose draconian measures on us is scary.$q$,'https://mainehousegop.org/member_news_item/maine-should-not-move-toward-eliminating-gas-powered-vehicles/','Maine House Republicans',true,$q$Verbatim sentence from Campbell's Dec. 13, 2023 op-ed on mainehousegop.org opposing Maine's proposed Advanced Clean Cars II / EV sales mandate; confirmed word-for-word on two independent fetches of the source page. No de-identification edits needed -- the sentence contains no name, party, or office identifier.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='1f6fb9ae-a29b-4174-baf3-1116371c4955' AND topic_key='climate-change' AND quote_text=$q$The fact that unelected bureaucrats have the power to impose draconian measures on us is scary.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '59df0b0d-f559-4e37-8f3a-1f8ae5b09485','trans-athletes',$q$I absolutely support the right to transition with proper guidance. But we also need to recognize that allowing trans athletes on all-girls' sports teams gives trans athletes an advantage that they would not otherwise have. And to me, to me, this is not fair.$q$,$q$I absolutely support the right to transition with proper guidance. But we also need to recognize that allowing trans athletes on all-girls' sports teams gives trans athletes an advantage that they would not otherwise have. And to me, to me, this is not fair.$q$,'https://www.mainepublic.org/politics/2025-06-13/maine-house-deadlocks-on-transgender-athletes-bill','Maine Public',true,$q$Verbatim quote from Maine Public's June 13, 2025 report on the House floor debate over LD 233; no de-identification edits needed, quote contains no name/party/district.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='59df0b0d-f559-4e37-8f3a-1f8ae5b09485' AND topic_key='trans-athletes' AND quote_text=$q$I absolutely support the right to transition with proper guidance. But we also need to recognize that allowing trans athletes on all-girls' sports teams gives trans athletes an advantage that they would not otherwise have. And to me, to me, this is not fair.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '59df0b0d-f559-4e37-8f3a-1f8ae5b09485','local-immigration',$q$Criminal networks do not stop at city or state lines, and neither should our collaboration as law enforcement agencies.$q$,$q$Criminal networks do not stop at city or state lines, and neither should our collaboration as law enforcement agencies.$q$,'https://mainemorningstar.com/2025/06/17/by-one-vote-maine-house-passes-restrictions-on-federal-immigration-enforcement/','Maine Morning Star',true,$q$Verbatim quote from Maine Morning Star's June 17, 2025 coverage of the LD 1971 House vote; no de-identification edits needed, quote contains no name/party/district.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='59df0b0d-f559-4e37-8f3a-1f8ae5b09485' AND topic_key='local-immigration' AND quote_text=$q$Criminal networks do not stop at city or state lines, and neither should our collaboration as law enforcement agencies.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'c9d094fe-1054-4804-bd24-f2cd6ceb748d','housing',$q$Bangor is at the center of Maine's housing crisis. I hear every day from people in my community who are living month-to-month or even day-to-day, wondering how they're going to pay rent and keep a roof over their heads. Making this tax credit permanent will allow us to continue addressing Maine's housing shortage, particularly for working families, seniors and rural communities.$q$,$q$[that district] is at the center of Maine's housing crisis. I hear every day from people in my community who are living month-to-month or even day-to-day, wondering how they're going to pay rent and keep a roof over their heads. Making this tax credit permanent will allow us to continue addressing Maine's housing shortage, particularly for working families, seniors and rural communities.$q$,'https://legislature.maine.gov/LawMakerWeb/summary.asp?LD=1522','Maine Legislature testimony',true,$q$Verbatim quote from a 4/3/2026 press release on maine.gov/housedems announcing House passage of LD 2116. De-identified by replacing the named city (Bangor) with [that district]; no other edits made.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='c9d094fe-1054-4804-bd24-f2cd6ceb748d' AND topic_key='housing' AND quote_text=$q$Bangor is at the center of Maine's housing crisis. I hear every day from people in my community who are living month-to-month or even day-to-day, wondering how they're going to pay rent and keep a roof over their heads. Making this tax credit permanent will allow us to continue addressing Maine's housing shortage, particularly for working families, seniors and rural communities.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'e6bd2fa6-6e8c-46e2-b13d-59f340a1a38f','jail-capacity',$q$If we can reduce dependence on county jails and emergency rooms and instead rely on mobile crisis services, we can save money.$q$,$q$If we can reduce dependence on county jails and emergency rooms and instead rely on mobile crisis services, we can save money.$q$,'https://www.bangordailynews.com/2021/04/15/opinion/opinion-contributor/mental-health-crises-can-happen-at-any-time-and-need-24-7-responses/','Bangor Daily News',true,$q$From Supica's own April 2021 Bangor Daily News op-ed explaining why she introduced legislation funding mobile mental-health crisis response; the quote is her forward-looking policy argument for treating mental health crises outside the jail/ER system, matching the jail-capacity topic's community-alternatives framing. Verbatim, no edits — the sentence contains no names, offices, or party references to strip.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='e6bd2fa6-6e8c-46e2-b13d-59f340a1a38f' AND topic_key='jail-capacity' AND quote_text=$q$If we can reduce dependence on county jails and emergency rooms and instead rely on mobile crisis services, we can save money.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'e6bd2fa6-6e8c-46e2-b13d-59f340a1a38f','housing',$q$Service center communities like Bangor and Portland often take in and provide support to folks from around the state seeking housing and services.$q$,$q$Service center communities like [this legislator's city] and [another city] often take in and provide support to folks from around the state seeking housing and services.$q$,'https://www.maine.gov/housedems/news/supica-praises-funding-affordable-housing-projects-support-emergency-shelters','Maine House Democrats',true,$q$Verbatim quote from Supica's July 2021 Maine House Democrats press release praising ARPA-funded affordable housing/shelter allocations; de-identified by replacing the two named cities with generic city references since they could help identify the speaker's district.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='e6bd2fa6-6e8c-46e2-b13d-59f340a1a38f' AND topic_key='housing' AND quote_text=$q$Service center communities like Bangor and Portland often take in and provide support to folks from around the state seeking housing and services.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '9c446f79-a394-4d25-85a6-31304ae1ec58','climate-change',$q$It is time for major oil and gas companies to pay their fair share, ease the burden on Maine taxpayers and help us build a more resilient future together.$q$,$q$It is time for major oil and gas companies to pay their fair share, ease the burden on Maine taxpayers and help us build a more resilient future together.$q$,'https://legislature.maine.gov/legis/bills/getTestimonyDoc.asp?id=10049832','Maine Legislature testimony',true,$q$Verbatim closing line from Faircloth's May 5, 2025 written testimony supporting LD 1870 (Climate Superfund Cost Recovery Program), read directly from the cached testimony PDF at the source URL. It documents his call for oil and gas companies -- not taxpayers -- to fund climate costs, supporting the clean-energy/climate-resilience stance. No de-identification edits were needed: the clause contains no name, party, or office identifier (the bare state name "Maine" is not considered identifying).$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='9c446f79-a394-4d25-85a6-31304ae1ec58' AND topic_key='climate-change' AND quote_text=$q$It is time for major oil and gas companies to pay their fair share, ease the burden on Maine taxpayers and help us build a more resilient future together.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '40e26806-48fe-492c-ac87-0be7715cc4b0','climate-change',$q$"LD 1777 at least could serve as a first step in real NEB reform, which has been needed since 2019."$q$,$q$"LD 1777 at least could serve as a first step in real NEB reform, which has been needed since 2019."$q$,'https://www.themainewire.com/2025/06/national-pro-solar-group-works-to-kill-a-bipartisan-bill-to-reduce-some-of-the-harms-of-net-energy-billing/','The Maine Wire',true,$q$Verbatim quote from a Maine Wire report on the 2025 net-energy-billing reform debate, no edits needed as the quote contains no name, party, or office markers. It documents a preference for further reducing state-driven renewable-subsidy costs rather than expanding the clean-energy mandate.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='40e26806-48fe-492c-ac87-0be7715cc4b0' AND topic_key='climate-change' AND quote_text=$q$"LD 1777 at least could serve as a first step in real NEB reform, which has been needed since 2019."$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'ecb8eddd-c6e2-4e90-a239-d98f4d7e0542','ukraine-support',$q$"We listened to everyone speak here today when we should be listening to the problems the people in Maine have."$q$,$q$"We listened to everyone speak here today when we should be listening to the problems the people in Maine have."$q$,'https://www.themainewire.com/2023/03/maine-legislature-spends-more-than-an-hour-debating-symbolic-ukraine-resolution/','The Maine Wire',true,$q$Verbatim quote from a Maine Wire account of a 2023 House floor debate over a Ukraine-support resolution, no de-identifying edits were needed since the quote names no individual, party, or office (the bare state name Maine is not identifying). It documents a preference for prioritizing domestic issues over continued attention and resources to Ukraine.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='ecb8eddd-c6e2-4e90-a239-d98f4d7e0542' AND topic_key='ukraine-support' AND quote_text=$q$"We listened to everyone speak here today when we should be listening to the problems the people in Maine have."$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'cce50333-2b4e-48f0-987c-7d1b579ee691','climate-change',$q$"The persistent claim that wind and solar are the cheapest form of generation makes for an effective talking point, but it does not hold up when customers pay their bills."$q$,$q$"The persistent claim that wind and solar are the cheapest form of generation makes for an effective talking point, but it does not hold up when customers pay their bills."$q$,'https://www.themainewire.com/2026/05/rep-reagan-paul-requests-that-maine-doe-assess-true-hidden-costs-of-green-energy-agenda/','The Maine Wire',true,$q$Verbatim quote from a Maine Wire report on a May 2026 letter to Maine's Department of Energy Resources, no de-identifying edits were needed since the quote contains no name, party, or office markers. It documents skepticism toward state-subsidized renewable-energy cost claims, consistent with favoring a more market-driven approach to the clean-energy transition.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='cce50333-2b4e-48f0-987c-7d1b579ee691' AND topic_key='climate-change' AND quote_text=$q$"The persistent claim that wind and solar are the cheapest form of generation makes for an effective talking point, but it does not hold up when customers pay their bills."$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '4bbdb54e-664a-437e-9c2d-2c6939bf44c5','taxes',$q$With $10.8 billion dollars at its disposal, the partisan budget rammed through by Democrats should contain structural income tax relief.$q$,$q$With $10.8 billion dollars at its disposal, the … budget should contain structural income tax relief.$q$,'https://mainehousegop.org/member_news_item/legislature-is-out-of-touch-with-people-trying-to-survive/','Maine House Republicans',true,$q$Verbatim sentence from Simmons' July 7, 2023 radio address posted on the House Republican caucus site (mainehousegop.org), arguing state budgets should include broader tax relief; his own forward-looking policy view, matching the taxes topic's chair 4. De-identified by cutting the partisan phrase "rammed through by Democrats" (a party-identifying tell) and marking the cut with an ellipsis; no other edits made.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='4bbdb54e-664a-437e-9c2d-2c6939bf44c5' AND topic_key='taxes' AND quote_text=$q$With $10.8 billion dollars at its disposal, the partisan budget rammed through by Democrats should contain structural income tax relief.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'b3737c12-af18-4419-b2f1-27ab6a599457','transportation-priorities',$q$Without consistent ferry service, families cannot comfortably live on an island, children cannot easily attend school and small businesses cannot thrive.$q$,$q$Without consistent ferry service, families cannot comfortably live on an island, children cannot easily attend school and small businesses cannot thrive.$q$,'https://www.maine.gov/housedems/news/crafts-introduces-legislation-study-feasibility-ferry-service-monhegan-island','Maine House Democrats',true,$q$Verbatim quote from an April 30, 2025 House Democratic caucus press release announcing Crafts' introduction of LD 1186 (Monhegan Island ferry-service feasibility study); it is her own forward-looking argument for why the transit connection is needed, matching the transportation-priorities topic's chair 3. No de-identification edits needed -- the sentence names no person, party, or office, and the unnamed island reference is not identifying.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='b3737c12-af18-4419-b2f1-27ab6a599457' AND topic_key='transportation-priorities' AND quote_text=$q$Without consistent ferry service, families cannot comfortably live on an island, children cannot easily attend school and small businesses cannot thrive.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '2d5859a0-18ba-42d2-b272-fb9acd9890a1','housing',$q$Homeownership is the key to building generational wealth and putting down roots in a community, but it's become a dream that's out of reach for working people.$q$,$q$Homeownership is the key to building generational wealth and putting down roots in a community, but it's become a dream that's out of reach for working people.$q$,'https://www.maine.gov/housedems/news/farrin-introduces-legislation-reduce-mortgage-costs-maine-homebuyers','Maine House Democrats',true,$q$Verbatim quote from the Jan. 22, 2026 House Democratic caucus press release announcing Farrin's introduction of LD 2077 (mortgage-rate-reduction grants); it is his own forward-looking rationale for the targeted homebuyer-subsidy bill, matching the housing topic's chair 3. No de-identification edits needed -- the sentence contains no name, party, or office identifier.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='2d5859a0-18ba-42d2-b272-fb9acd9890a1' AND topic_key='housing' AND quote_text=$q$Homeownership is the key to building generational wealth and putting down roots in a community, but it's become a dream that's out of reach for working people.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '0316ee2f-fe0c-4122-a95a-2f43f55ce260','jail-capacity',$q$There is no increased risk to the public if this bill is passed. But what there is for the public is a significant lightening of the court's criminal dockets.$q$,$q$There is no increased risk to the public if this bill is passed. But what there is for the public is a significant lightening of the court's criminal dockets.$q$,'https://www.themainewire.com/2025/02/there-is-no-increased-risk-to-the-public-maine-democrat-wants-to-repeal-the-crime-of-violating-bail-to-reduce-case-backlog/','The Maine Wire',true,$q$From Feb. 3, 2025 committee testimony introducing LD 179 (bail code reform), reported by The Maine Wire; verbatim, no edits. Shows his forward-looking case for reducing incarceration via bail reform, aligning with stance 2.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='0316ee2f-fe0c-4122-a95a-2f43f55ce260' AND topic_key='jail-capacity' AND quote_text=$q$There is no increased risk to the public if this bill is passed. But what there is for the public is a significant lightening of the court's criminal dockets.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'c08c1cf6-c505-4490-a1a3-be7945b8f2f2','homelessness',$q$It is not a tool for shutting down community-based responses to homelessness. It is not a license for municipalities to say no to emergency housing efforts out of fear or misunderstanding.$q$,$q$It is not a tool for shutting down community-based responses to homelessness. It is not a license for municipalities to say no to emergency housing efforts out of fear or misunderstanding.$q$,'https://legislature.maine.gov/legis/bills/getTestimonyDoc.asp?id=188572','Maine Legislature testimony',true,$q$From his April 8, 2025 testimony introducing LD 1179 before the Housing and Economic Development Committee; verbatim, no edits. Shows his forward-looking view that shelter safety standards should expand, not block, community responses to homelessness, aligning with stance 2.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='c08c1cf6-c505-4490-a1a3-be7945b8f2f2' AND topic_key='homelessness' AND quote_text=$q$It is not a tool for shutting down community-based responses to homelessness. It is not a license for municipalities to say no to emergency housing efforts out of fear or misunderstanding.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '8b1dca67-2cfa-456f-81b0-27cab1690388','medicare/aid',$q$We cannot tolerate waste, fraud, and abuse in this vital social safety net. There is mounting evidence that this is occurring at levels beyond comprehension.$q$,$q$We cannot tolerate waste, fraud, and abuse in this vital social safety net. There is mounting evidence that this is occurring at levels beyond comprehension.$q$,'https://mainehousegop.org/member_news_item/representative-lemelin-named-lead-on-health-and-human-services-committee/','Maine House Republicans',true,$q$From a Feb. 4, 2026 Maine House GOP release on his committee assignment; verbatim, no edits. Shows his forward-looking priority of policing waste/fraud in MaineCare while preserving the program itself, aligning with stance 3.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='8b1dca67-2cfa-456f-81b0-27cab1690388' AND topic_key='medicare/aid' AND quote_text=$q$We cannot tolerate waste, fraud, and abuse in this vital social safety net. There is mounting evidence that this is occurring at levels beyond comprehension.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '8b1dca67-2cfa-456f-81b0-27cab1690388','taxes',$q$The government that governs best, is the government that governs the least.$q$,$q$The government that governs best, is the government that governs the least.$q$,'https://mainehousegop.org/member_news_item/government-now-has-an-extra-1-2-billion-of-your-money/','Maine House Republicans',true,$q$From a March 4, 2022 Maine House GOP radio address on the state budget surplus, republished on his caucus site; verbatim, no edits. Shows his general small-government tax philosophy, corroborated by his 2025 Nay vote against a tax-bracket increase, aligning with stance 4.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='8b1dca67-2cfa-456f-81b0-27cab1690388' AND topic_key='taxes' AND quote_text=$q$The government that governs best, is the government that governs the least.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '4fcdb98d-b61f-499d-8d19-8f9462c907dd','taxes',$q$The Republicans, on the other hand, want to lower taxes. We want sustainable tax relief.$q$,$q$[Political party] want to lower taxes. [They] want sustainable tax relief.$q$,'https://mesenategop.com/2026/02/13/republican-vision-for-maine-real-relief-for-maine-taxpayers/','Maine Senate Republicans',true,$q$Verbatim quote from Sen. Bernard's own words in a Feb. 13, 2026 Maine Senate Republicans staff-report interview (mesenategop.com); de-identified by replacing party label and pronoun.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='4fcdb98d-b61f-499d-8d19-8f9462c907dd' AND topic_key='taxes' AND quote_text=$q$The Republicans, on the other hand, want to lower taxes. We want sustainable tax relief.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '4fcdb98d-b61f-499d-8d19-8f9462c907dd','medicare/aid',$q$We don't want to gut MaineCare – rather, we need to take immediate steps to reverse the problem and ensure MaineCare's long-term sustainability.$q$,$q$[They] don't want to gut [the state Medicaid program] – rather, [they] need to take immediate steps to reverse the problem and ensure [the program]'s long-term sustainability.$q$,'https://mesenategop.com/2025/02/16/republicans-stand-ready-to-make-tough-budget-decisions/','Maine Senate Republicans',true,$q$Verbatim quote from Sen. Bernard's Feb. 16, 2025 Republican Radio Address, published on mesenategop.com; de-identified by replacing the program's proper name and pronoun.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='4fcdb98d-b61f-499d-8d19-8f9462c907dd' AND topic_key='medicare/aid' AND quote_text=$q$We don't want to gut MaineCare – rather, we need to take immediate steps to reverse the problem and ensure MaineCare's long-term sustainability.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '4fcdb98d-b61f-499d-8d19-8f9462c907dd','healthcare',$q$Republicans also introduced amendments aimed at returning MaineCare back to the program it was meant to be – a safety net to help Maine's most needy residents.$q$,$q$[They] also introduced amendments aimed at returning [the state Medicaid program] back to the program it was meant to be – a safety net to help [the state]'s most needy residents.$q$,'https://mesenategop.com/2025/02/16/republicans-stand-ready-to-make-tough-budget-decisions/','Maine Senate Republicans',true,$q$Verbatim quote from Sen. Bernard's Feb. 16, 2025 Republican Radio Address, published on mesenategop.com; de-identified by replacing the program's proper name and state name.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='4fcdb98d-b61f-499d-8d19-8f9462c907dd' AND topic_key='healthcare' AND quote_text=$q$Republicans also introduced amendments aimed at returning MaineCare back to the program it was meant to be – a safety net to help Maine's most needy residents.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '9a76f4d8-61d0-4a4b-a5d2-cff71b608f05','taxes',$q$We have been crystal clear since November that we would not support a budget if it does not contain substantive tax relief for Mainers.$q$,$q$[They] have been crystal clear since November that [they] would not support a budget if it does not contain substantive tax relief for [state] residents.$q$,'https://mesenategop.com/2026/04/09/legislative-democrats-continue-their-years-long-spending-spree/','Maine Senate Republicans',true,$q$Verbatim quote from Sen. Stewart's Apr. 9, 2026 statement, published on mesenategop.com; de-identified by replacing pronoun and state name.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='9a76f4d8-61d0-4a4b-a5d2-cff71b608f05' AND topic_key='taxes' AND quote_text=$q$We have been crystal clear since November that we would not support a budget if it does not contain substantive tax relief for Mainers.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '9a76f4d8-61d0-4a4b-a5d2-cff71b608f05','medicare/aid',$q$MaineCare has a serious sustainability problem. It's incumbent upon the Legislature to rein in this program by both reducing fraud and making sure healthy adults on the program can better themselves and get off taxpayer-funded healthcare.$q$,$q$[The state Medicaid program] has a serious sustainability problem. It's incumbent upon the Legislature to rein in this program by both reducing fraud and making sure healthy adults on the program can better themselves and get off taxpayer-funded healthcare.$q$,'https://mesenategop.com/2026/03/10/sen-stewart-proposes-legislation-to-address-mainecare-integrity-and-sustainability-concerns/','Maine Senate Republicans',true,$q$Verbatim quote from Sen. Stewart's Mar. 10, 2026 legislative-proposal press release, published on mesenategop.com; de-identified by replacing the program's proper name.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='9a76f4d8-61d0-4a4b-a5d2-cff71b608f05' AND topic_key='medicare/aid' AND quote_text=$q$MaineCare has a serious sustainability problem. It's incumbent upon the Legislature to rein in this program by both reducing fraud and making sure healthy adults on the program can better themselves and get off taxpayer-funded healthcare.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '9a76f4d8-61d0-4a4b-a5d2-cff71b608f05','school-vouchers',$q$There would be a fully refundable tax credit for anybody in Maine that right now we're missing out on because the Democrats haven't adopted it.$q$,$q$There would be a fully refundable tax credit for anybody in [that state] that right now [they're] missing out on because [the opposing party] haven't adopted it.$q$,'https://mesenategop.com/2025/11/07/republican-vision-for-maine-improving-outcomes-and-increasing-choice-in-education/','Maine Senate Republicans',true,$q$Verbatim quote from Sen. Stewart's own remarks in a Nov. 7, 2025 Senate Republican interview piece, published on mesenategop.com; de-identified by replacing state name and party label.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='9a76f4d8-61d0-4a4b-a5d2-cff71b608f05' AND topic_key='school-vouchers' AND quote_text=$q$There would be a fully refundable tax credit for anybody in Maine that right now we're missing out on because the Democrats haven't adopted it.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'a49f9cab-2681-4003-a4a7-398c569cbaf5','voting-rights',$q$If they had just left it for voter ID, I think it probably would have been a slam dunk. Both sides want to win at all costs, and so it's an all-in battle on every topic instead of trying to find some compromise.$q$,$q$If they had just left it for voter ID, I think it probably would have been a slam dunk. Both sides want to win at all costs, and so it's an all-in battle on every topic instead of trying to find some compromise.$q$,'https://www.themainewire.com/2025/11/botched-voter-id-for-maine-effort-tanks-on-election-day/','The Maine Wire',true,$q$Verbatim quote from The Maine Wire, Nov. 2025 article about the defeated Question 1 voter-ID referendum. Quote contains no name/party/district markers, so no de-identification edits were needed beyond removing surrounding attribution.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='a49f9cab-2681-4003-a4a7-398c569cbaf5' AND topic_key='voting-rights' AND quote_text=$q$If they had just left it for voter ID, I think it probably would have been a slam dunk. Both sides want to win at all costs, and so it's an all-in battle on every topic instead of trying to find some compromise.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'a49f9cab-2681-4003-a4a7-398c569cbaf5','taxes',$q$Responsible Spending & Lower Taxes: The fight for accountability is never done.$q$,$q$Responsible Spending & Lower Taxes: The fight for accountability is never done.$q$,'https://bradfarrin.com','bradfarrin.com',true,$q$Verbatim tagline from the "Standing Up For" issues section of his official campaign site; no de-identification edits needed as the text contains no name/party/district markers.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='a49f9cab-2681-4003-a4a7-398c569cbaf5' AND topic_key='taxes' AND quote_text=$q$Responsible Spending & Lower Taxes: The fight for accountability is never done.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'd435e628-4145-41c3-9dc4-4ff2b91b9acf','trans-athletes',$q$Allowing biological males to compete in women's sports undermines opportunities for female athletes to reach their full potential and compete on a fair playing field.$q$,$q$Allowing biological males to compete in women's sports undermines opportunities for female athletes to reach their full potential and compete on a fair playing field.$q$,'https://mesenategop.com/2026/05/01/republican-vision-for-maine-standing-up-for-fairness-in-girls-sports/','Maine Senate Republicans',true,$q$Verbatim quote from her own Republican Radio Address published on the Maine Senate GOP site; no de-identification edits needed as the quote contains no name/party/district markers.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='d435e628-4145-41c3-9dc4-4ff2b91b9acf' AND topic_key='trans-athletes' AND quote_text=$q$Allowing biological males to compete in women's sports undermines opportunities for female athletes to reach their full potential and compete on a fair playing field.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '81db75c5-8c48-40f3-8cb1-7220def31e72','taxes',$q$Lower taxes on individuals and businesses to help Mainers keep more of what they earn$q$,$q$Lower taxes on individuals and businesses to help [state] residents keep more of what they earn$q$,'https://www.russellblackformaine.com/','www.russellblackformaine.com',true,$q$Verbatim from the "Taxes & Economy" section of Black's campaign platform page (russellblackformaine.com homepage). De-identified: state name generalized.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='81db75c5-8c48-40f3-8cb1-7220def31e72' AND topic_key='taxes' AND quote_text=$q$Lower taxes on individuals and businesses to help Mainers keep more of what they earn$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '81db75c5-8c48-40f3-8cb1-7220def31e72','childcare',$q$Expand access to affordable child care by bringing Maine regulations in line with National child-to-staff ratios$q$,$q$Expand access to affordable child care by bringing [state] regulations in line with National child-to-staff ratios$q$,'https://www.russellblackformaine.com/','www.russellblackformaine.com',true,$q$Verbatim from the "Childcare" section of Black's campaign platform page (russellblackformaine.com homepage). De-identified: state name generalized.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='81db75c5-8c48-40f3-8cb1-7220def31e72' AND topic_key='childcare' AND quote_text=$q$Expand access to affordable child care by bringing Maine regulations in line with National child-to-staff ratios$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '26583d91-4019-4832-bc2e-36c0672d878a','voting-rights',$q$For those without a driver's license or any other form of government-issued identification, the Department of the Secretary of State will be required to provide one, free of charge.$q$,$q$For those without a driver's license or any other form of government-issued identification, the Department of the Secretary of State will be required to provide one, free of charge.$q$,'https://mesenategop.com/2025/10/01/question-1-will-maintain-voting-accessibility-while-increasing-confidence-in-our-elections/','Maine Senate Republicans',true,$q$Verbatim from Sen. Moore's bylined column on mesenategop.com (Oct 1, 2025) arguing for Question 1. No de-identification needed beyond removing byline; quote itself contains no identifying terms.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='26583d91-4019-4832-bc2e-36c0672d878a' AND topic_key='voting-rights' AND quote_text=$q$For those without a driver's license or any other form of government-issued identification, the Department of the Secretary of State will be required to provide one, free of charge.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '1c14da77-9b45-478c-85b5-9b2f5dad1481','climate-change',$q$Renewable energy can be cheaper to build and operate than fossil-fuel generation.$q$,$q$Renewable energy can be cheaper to build and operate than fossil-fuel generation.$q$,'https://www.bangordailynews.com/profile/nicole-c-grohoski/','Bangor Daily News',true,$q$From Grohoski's October 2024 Bangor Daily News candidate questionnaire answer on meeting Maine's electricity demand; verbatim, no edits — the sentence contains no name, party, or office reference to strip.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='1c14da77-9b45-478c-85b5-9b2f5dad1481' AND topic_key='climate-change' AND quote_text=$q$Renewable energy can be cheaper to build and operate than fossil-fuel generation.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'f6fef6fa-30e2-4dac-9bf6-9b0250b24bd3','jail-capacity',$q$correct bail reform's over-reach because Maine's current bail laws are not working$q$,$q$correct bail reform's over-reach because … current bail laws are not working$q$,'https://www.themainewire.com/2025/04/sen-haggan-wants-judges-and-commissioners-to-have-more-say-over-who-gets-bail/','The Maine Wire',true,$q$From Haggan's committee testimony on his own bill LD 1536, as reported by The Maine Wire (April 24, 2025); one small cut (…) removed a state-name repetition, otherwise verbatim — no name/party/office references were present to strip.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='f6fef6fa-30e2-4dac-9bf6-9b0250b24bd3' AND topic_key='jail-capacity' AND quote_text=$q$correct bail reform's over-reach because Maine's current bail laws are not working$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'ceace463-1299-4c49-b5aa-e73af2534e0a','housing',$q$I am excited that the entire committee supports LD 554, which would give residents a leg up when they try to buy their homes.$q$,$q$I am excited that the entire committee supports LD 554, which would give residents a leg up when they try to buy their homes.$q$,'https://www.mainesenate.org/sen-cameron-renys-bill-to-create-tax-incentives-to-increase-the-supply-of-affordable-housing-in-maine-receives-unanimous-committee-support/','Maine Senate Democrats',true,$q$Verbatim quote from Sen. Reny's March 19, 2025 press release on mainesenate.org celebrating committee support for her affordable-housing tax-deduction bill; shows her framing the bill as targeted help for residents rather than a universal program, aligning with stance 3. No de-identifying edits were needed/made since the quote contains no name, party, district, or office reference beyond the public bill number, which is kept per style guide.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='ceace463-1299-4c49-b5aa-e73af2534e0a' AND topic_key='housing' AND quote_text=$q$I am excited that the entire committee supports LD 554, which would give residents a leg up when they try to buy their homes.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '7a6b6395-3308-4477-88f9-b5cb85722ee1','taxes',$q$It's time to take a hard look at how we spend your money and reduce taxes, fees, and the cost of living so you can keep more of your own money in your own pocket here in Maine.$q$,$q$It's time to take a hard look at how we spend your money and reduce taxes, fees, and the cost of living so you can keep more of your own money in your own pocket here in Maine.$q$,'https://www.dickbradstreet.com','www.dickbradstreet.com',true,$q$Verbatim quote from the "Reduce Taxes" bullet on Bradstreet's campaign issues page (dickbradstreet.com), dropping only the boldface bullet header ("Reduce Taxes –") which is a label, not part of the sentence; shows a general tax/fee/cost-of-living cut without singling out any income group, aligning with stance 4. No de-identifying edits were needed since the sentence contains no name, party, district, or office reference (the bare state name "Maine" is not identifying and is kept per style guide).$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='7a6b6395-3308-4477-88f9-b5cb85722ee1' AND topic_key='taxes' AND quote_text=$q$It's time to take a hard look at how we spend your money and reduce taxes, fees, and the cost of living so you can keep more of your own money in your own pocket here in Maine.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'dc583785-9207-41b7-a790-1bc87e0685de','taxes',$q$Mainers won't be able to take full advantage of the federal tax cuts unless the Legislature acts.$q$,$q$Mainers won't be able to take full advantage of the federal tax cuts unless the Legislature acts.$q$,'https://mesenategop.com/2026/01/02/a-new-year-a-new-legislative-session/','Maine Senate Republicans',true,$q$From Cyrway's Jan. 2, 2026 Maine Senate Republicans radio address (mesenategop.com), verbatim, no edits — contains no identifying markers to strip. Shows his forward push for state tax cuts, supporting stance 4.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='dc583785-9207-41b7-a790-1bc87e0685de' AND topic_key='taxes' AND quote_text=$q$Mainers won't be able to take full advantage of the federal tax cuts unless the Legislature acts.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'dc583785-9207-41b7-a790-1bc87e0685de','deportation',$q$LD 1971 is a truly dangerous piece of legislation that will prevent our law enforcement officers from cooperating with federal authorities to take dangerous criminals off our streets.$q$,$q$LD 1971 is a truly dangerous piece of legislation that will prevent our law enforcement officers from cooperating with federal authorities to take dangerous criminals off our streets.$q$,'https://mesenategop.com/2026/01/02/a-new-year-a-new-legislative-session/','Maine Senate Republicans',true,$q$From Cyrway's Jan. 2, 2026 radio address (mesenategop.com), verbatim, no edits — LD 1971 is a bill number, not an identity leak. Shows his forward opposition to restricting local-federal immigration enforcement cooperation, aligning with stance 4.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='dc583785-9207-41b7-a790-1bc87e0685de' AND topic_key='deportation' AND quote_text=$q$LD 1971 is a truly dangerous piece of legislation that will prevent our law enforcement officers from cooperating with federal authorities to take dangerous criminals off our streets.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'dc583785-9207-41b7-a790-1bc87e0685de','climate-change',$q$legislative Republicans will continue to support policies to lower Mainers' energy costs.$q$,$q$legislative [lawmakers] will continue to support policies to lower Mainers' energy costs.$q$,'https://mesenategop.com/2026/01/02/a-new-year-a-new-legislative-session/','Maine Senate Republicans',true,$q$From Cyrway's Jan. 2, 2026 radio address (mesenategop.com); quote_deidentified substitutes '[lawmakers]' for 'Republicans' to remove the party tell. Follows his critique of $450M in solar subsidies benefiting out-of-state developers, supporting stance 4.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='dc583785-9207-41b7-a790-1bc87e0685de' AND topic_key='climate-change' AND quote_text=$q$legislative Republicans will continue to support policies to lower Mainers' energy costs.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'f6c4c795-fac0-4b57-8b6e-0ae57515f941','taxes',$q$We will not support any new or increased taxes and fees.$q$,$q$We will not support any new or increased taxes and fees.$q$,'https://mesenategop.com/2025/05/09/democrat-budget-shenanigans-continue/','Maine Senate Republicans',true,$q$From Timberlake's May 9, 2025 radio address (mesenategop.com), verbatim, no edits — the preceding party-identifying clause ('Republicans have been very clear...') was excluded from the quote itself. Shows his forward opposition to new taxes/fees, aligning with stance 3.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='f6c4c795-fac0-4b57-8b6e-0ae57515f941' AND topic_key='taxes' AND quote_text=$q$We will not support any new or increased taxes and fees.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'f6c4c795-fac0-4b57-8b6e-0ae57515f941','medicare/aid',$q$One of our simple requests is that able-bodied childless adults need to engage in work or community engagement to further themselves.$q$,$q$One of our simple requests is that able-bodied childless adults need to engage in work or community engagement to further themselves.$q$,'https://mesenategop.com/2025/05/09/democrat-budget-shenanigans-continue/','Maine Senate Republicans',true,$q$From Timberlake's May 9, 2025 radio address (mesenategop.com), verbatim, no edits. Documents his forward proposal to add MaineCare work requirements for able-bodied childless adults, supporting stance 4.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='f6c4c795-fac0-4b57-8b6e-0ae57515f941' AND topic_key='medicare/aid' AND quote_text=$q$One of our simple requests is that able-bodied childless adults need to engage in work or community engagement to further themselves.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'e73bd689-240f-492a-bf01-f7be307367f8','healthcare',$q$We need to make coverage more affordable because every Mainer deserves access to the care they need without being buried in paperwork and medical debt.$q$,$q$We need to make coverage more affordable because every Mainer deserves access to the care they need without being buried in paperwork and medical debt.$q$,'https://bennettforgovernor.com/vision','bennettforgovernor.com',true,$q$From Bennett's 2026 gubernatorial 'Vision for Maine' platform page (bennettforgovernor.com/vision), verbatim, no edits. Shows his forward call for universal, affordable healthcare access, supporting stance 2.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='e73bd689-240f-492a-bf01-f7be307367f8' AND topic_key='healthcare' AND quote_text=$q$We need to make coverage more affordable because every Mainer deserves access to the care they need without being buried in paperwork and medical debt.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'e73bd689-240f-492a-bf01-f7be307367f8','taxes',$q$Maine people work hard and deserve a fair, transparent tax system that reflects that.$q$,$q$Maine people work hard and deserve a fair, transparent tax system that reflects that.$q$,'https://bennettforgovernor.com/vision','bennettforgovernor.com',true,$q$Maine people work hard and deserve a fair$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='e73bd689-240f-492a-bf01-f7be307367f8' AND topic_key='taxes' AND quote_text=$q$Maine people work hard and deserve a fair, transparent tax system that reflects that.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'e73bd689-240f-492a-bf01-f7be307367f8','climate-change',$q$We need to put affordability first while moving toward true energy independence.$q$,$q$We need to put affordability first while moving toward true energy independence.$q$,'https://bennettforgovernor.com/vision','bennettforgovernor.com',true,$q$From Bennett's 2026 gubernatorial 'Vision for Maine' platform (bennettforgovernor.com/vision), verbatim, no edits. Shows his forward energy-investment framing supporting stance 3.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='e73bd689-240f-492a-bf01-f7be307367f8' AND topic_key='climate-change' AND quote_text=$q$We need to put affordability first while moving toward true energy independence.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'e73bd689-240f-492a-bf01-f7be307367f8','housing',$q$We need to double the rate of new homes being built while also streamlining the regulatory process that prioritizes efficiency and labor standards.$q$,$q$We need to double the rate of new homes being built while also streamlining the regulatory process that prioritizes efficiency and labor standards.$q$,'https://bennettforgovernor.com/vision','bennettforgovernor.com',true,$q$From Bennett's 2026 gubernatorial 'Vision for Maine' platform (bennettforgovernor.com/vision), verbatim, no edits. Documents his forward housing-supply proposal supporting stance 3.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='e73bd689-240f-492a-bf01-f7be307367f8' AND topic_key='housing' AND quote_text=$q$We need to double the rate of new homes being built while also streamlining the regulatory process that prioritizes efficiency and labor standards.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'e73bd689-240f-492a-bf01-f7be307367f8','childcare',$q$a childcare system that offers affordable options in every community, support for providers so they can stay open and pay a livable wage, and policies that make childcare more accessible$q$,$q$a childcare system that offers affordable options in every community, support for providers so they can stay open and pay a livable wage, and policies that make childcare more accessible$q$,'https://bennettforgovernor.com/vision','bennettforgovernor.com',true,$q$From Bennett's 2026 gubernatorial 'Vision for Maine' platform (bennettforgovernor.com/vision), verbatim, no edits. Shows his forward childcare subsidy/provider-support proposal, supporting stance 2.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='e73bd689-240f-492a-bf01-f7be307367f8' AND topic_key='childcare' AND quote_text=$q$a childcare system that offers affordable options in every community, support for providers so they can stay open and pay a livable wage, and policies that make childcare more accessible$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'e73bd689-240f-492a-bf01-f7be307367f8','campaign-finance',$q$I'll strengthen disclosure laws, make decisions transparent, and ensure that dark money and hidden donors can't steer outcomes behind the scenes.$q$,$q$I'll strengthen disclosure laws, make decisions transparent, and ensure that dark money and hidden donors can't steer outcomes behind the scenes.$q$,'https://bennettforgovernor.com/vision','bennettforgovernor.com',true,$q$and ensure that dark money and hidden donors can't steer outcomes behind the scenes.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='e73bd689-240f-492a-bf01-f7be307367f8' AND topic_key='campaign-finance' AND quote_text=$q$I'll strengthen disclosure laws, make decisions transparent, and ensure that dark money and hidden donors can't steer outcomes behind the scenes.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'e73bd689-240f-492a-bf01-f7be307367f8','abortion',$q$True freedom also means making personal decisions about one's own body, health, and life without government intrusion.$q$,$q$True freedom also means making personal decisions about one's own body, health, and life without government intrusion.$q$,'https://bennettforgovernor.com/vision','bennettforgovernor.com',true,$q$and life without government intrusion.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='e73bd689-240f-492a-bf01-f7be307367f8' AND topic_key='abortion' AND quote_text=$q$True freedom also means making personal decisions about one's own body, health, and life without government intrusion.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '90e18f37-3ae3-4466-8f56-1f1bcecdac7d','taxes',$q$That means affordable energy, lower taxes, predictable regulations, respect for local communities and policies that encourage investment and stay right the hell out of the way instead of treating employers as a problem to be managed.$q$,$q$That means affordable energy, lower taxes, predictable regulations, respect for local communities and policies that encourage investment and stay right the hell out of the way instead of treating employers as a problem to be managed.$q$,'https://mesenategop.com/2026/06/18/maines-business-climate-is-failing-and-we-know-why/','Maine Senate Republicans',true,$q$From Sen. Martin's June 2026 column 'Maine's business climate is failing — and we know why' on mesenategop.com; verbatim, no de-identification edits needed since the quote contains no names, party, or state references.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='90e18f37-3ae3-4466-8f56-1f1bcecdac7d' AND topic_key='taxes' AND quote_text=$q$That means affordable energy, lower taxes, predictable regulations, respect for local communities and policies that encourage investment and stay right the hell out of the way instead of treating employers as a problem to be managed.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '90e18f37-3ae3-4466-8f56-1f1bcecdac7d','climate-change',$q$the climate change advocates keep taking billions of dollars every year out of our economy. It needs to stop.$q$,$q$the climate change advocates keep taking billions of dollars every year out of our economy. It needs to stop.$q$,'https://mesenategop.com/2025/12/19/republican-vision-for-maine-environmental-stewardship-and-economic-opportunity-can-go-hand-in-hand/','Maine Senate Republicans',true,$q$From Sen. Martin's December 2025 column on mesenategop.com; verbatim, no de-identification edits needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='90e18f37-3ae3-4466-8f56-1f1bcecdac7d' AND topic_key='climate-change' AND quote_text=$q$the climate change advocates keep taking billions of dollars every year out of our economy. It needs to stop.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'fc62e5af-90bc-42ad-90a5-6d0a586331e8','school-vouchers',$q$Their school choice allows parents to take a look at the actual amount of money that's being designated for the student. They can look at it, and the money follows the child.$q$,$q$Their school choice allows parents to take a look at the actual amount of money that's being designated for the student. They can look at it, and the money follows the child.$q$,'https://mesenategop.com/2025/11/07/republican-vision-for-maine-improving-outcomes-and-increasing-choice-in-education/','Maine Senate Republicans',true,$q$From Sen. Libby's November 2025 column on mesenategop.com describing Arizona's school-choice model, which he says Maine should emulate; verbatim, no de-identification edits needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='fc62e5af-90bc-42ad-90a5-6d0a586331e8' AND topic_key='school-vouchers' AND quote_text=$q$Their school choice allows parents to take a look at the actual amount of money that's being designated for the student. They can look at it, and the money follows the child.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'fc62e5af-90bc-42ad-90a5-6d0a586331e8','climate-change',$q$When government starts limiting choice – whether it's how you heat your home or what powers the car you drive – we cross the line in tipping the scales in favor of one industry over another.$q$,$q$When government starts limiting choice – whether it's how you heat your home or what powers the car you drive – we cross the line in tipping the scales in favor of one industry over another.$q$,'https://mesenategop.com/2024/07/29/when-it-comes-to-energy-policy-market-principles-should-be-considered/','Maine Senate Republicans',true,$q$From Sen. Libby's July 2024 radio address on mesenategop.com; verbatim, no de-identification edits needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='fc62e5af-90bc-42ad-90a5-6d0a586331e8' AND topic_key='climate-change' AND quote_text=$q$When government starts limiting choice – whether it's how you heat your home or what powers the car you drive – we cross the line in tipping the scales in favor of one industry over another.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '0ed25b30-633f-45f5-99f1-a32009b134f5','medicare/aid',$q$MaineCare isn't just a program — it's a lifeline. We are not asking for a luxury. We are demanding basic human dignity.$q$,$q$MaineCare isn't just a program — it's a lifeline. We are not asking for a luxury. We are demanding basic human dignity.$q$,'https://www.mainesenate.org/maine-legislators-advocate-for-protecting-federal-mainecare-funding-safeguarding-healthcare-access/','Maine Senate Democrats',true,$q$From a May 2025 mainesenate.org press release quoting Senate President Daughtry on protecting federal MaineCare funding; trimmed to the first three sentences of a longer quoted passage, otherwise verbatim; no de-identification edits needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='0ed25b30-633f-45f5-99f1-a32009b134f5' AND topic_key='medicare/aid' AND quote_text=$q$MaineCare isn't just a program — it's a lifeline. We are not asking for a luxury. We are demanding basic human dignity.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '0ed25b30-633f-45f5-99f1-a32009b134f5','childcare',$q$The gaps in our state's early childhood education system are too serious — and too urgent — to address from behind a desk.$q$,$q$The gaps in our state's early childhood education system are too serious — and too urgent — to address from behind a desk.$q$,'https://www.pressherald.com/2025/09/08/what-lawmakers-are-hearing-about-child-care-in-maine/','Portland Press Herald',true,$q$From a September 2025 Portland Press Herald article quoting Sen. Daughtry on her statewide childcare listening tour; verbatim, no de-identification edits needed.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='0ed25b30-633f-45f5-99f1-a32009b134f5' AND topic_key='childcare' AND quote_text=$q$The gaps in our state's early childhood education system are too serious — and too urgent — to address from behind a desk.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '69fece92-eade-468e-bf34-82bbac5b3da9','abortion',$q$We are fortunate to live in a state that protects reproductive rights and access to care.$q$,$q$We are fortunate to live in a state that protects reproductive rights and access to care.$q$,'https://www.mainesenate.org/sen-pierce-scores-100-on-reproductive-rights-voting-record-in-132nd-legislature/','Maine Senate Democrats',true,$q$Verbatim opening line from Sen. Pierce's June 2026 statement after earning a perfect Planned Parenthood Maine Action Fund score for opposing seven abortion-restriction bills in the 132nd Legislature. No de-identification edits needed -- this sentence contains no name, party, or office markers.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='69fece92-eade-468e-bf34-82bbac5b3da9' AND topic_key='abortion' AND quote_text=$q$We are fortunate to live in a state that protects reproductive rights and access to care.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '69fece92-eade-468e-bf34-82bbac5b3da9','healthcare',$q$The role that family planning centers play in our communities cannot be understated.$q$,$q$The role that family planning centers play in our communities cannot be understated.$q$,'https://www.bangordailynews.com/2024/02/27/opinion/opinion-contributor/maine-family-planning-centers-need-funding/','Bangor Daily News',true,$q$Verbatim line from Sen. Pierce's Feb. 2024 Bangor Daily News op-ed advocating for stable state funding of Maine Family Planning community health centers. No de-identification edits needed -- sentence contains no name, party, or office markers.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='69fece92-eade-468e-bf34-82bbac5b3da9' AND topic_key='healthcare' AND quote_text=$q$The role that family planning centers play in our communities cannot be understated.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'b8bac865-38a9-45f7-8641-ebdedf416f30','abortion',$q$These are deeply personal medical decisions that should be made by patients, their families and their doctors — not politicians.$q$,$q$These are deeply personal medical decisions that should be made by patients, their families and their doctors — not politicians.$q$,'https://mainerighttolife.org/wp-content/uploads/2025/07/2025-132nd-Senate-Roll-Call.pdf','mainerighttolife.org',true,$q$Verbatim excerpt from Sen. Nangle's June 25, 2026 mainesenate.org press release celebrating his 100% Planned Parenthood Maine Action Fund score; selected only the general-principle sentence and omitted his preceding self-identifying clause ("As a former healthcare professional, I have always believed that reproductive care is healthcare") to avoid a biographical tell. Shows his forward view that abortion decisions belong to patients and doctors, not government, supporting stance 1.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='b8bac865-38a9-45f7-8641-ebdedf416f30' AND topic_key='abortion' AND quote_text=$q$These are deeply personal medical decisions that should be made by patients, their families and their doctors — not politicians.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'b8bac865-38a9-45f7-8641-ebdedf416f30','housing',$q$Housing is stability, it's safety and it's the foundation for everything else.$q$,$q$Housing is stability, it's safety and it's the foundation for everything else.$q$,'https://www.mainesenate.org/sen-nangle-introduces-bill-to-keep-maine-veterans-housed/','Maine Senate Democrats',true,$q$Verbatim sentence from Sen. Nangle's January 27, 2026 mainesenate.org release introducing his veterans-housing bill (LD 2135); trimmed the preceding sentence referencing military service to keep only his general housing-values statement. No de-identifying edits were needed on this sentence — it contains no name, party, district, or office reference. Shows his forward framing of housing as a foundational need, supporting a targeted-assistance approach (stance 3).$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='b8bac865-38a9-45f7-8641-ebdedf416f30' AND topic_key='housing' AND quote_text=$q$Housing is stability, it's safety and it's the foundation for everything else.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'b8bac865-38a9-45f7-8641-ebdedf416f30','transportation-priorities',$q$Whether it's paving roads in Windham or improving transit planning in Westbrook, this work plan helps strengthen the connections our families, businesses and towns rely on every day.$q$,$q$Whether it's paving roads in [one town] or improving transit planning in [another], this work plan helps strengthen the connections our families, businesses and towns rely on every day.$q$,'https://www.mainesenate.org/sen-nangle-shares-2025-mdot-work-plan-for-state-bridge-and-road-projects/','Maine Senate Democrats',true,$q$Verbatim quote from Sen. Nangle's March 31, 2025 mainesenate.org release on the MDOT work plan for his Senate district; de-identified by replacing the two specific town names (a fairly unique pairing for his district) with generic bracketed placeholders. Shows his forward framing of a work plan spanning both road paving and transit planning, supporting the roads-plus-selective-transit approach of stance 3.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='b8bac865-38a9-45f7-8641-ebdedf416f30' AND topic_key='transportation-priorities' AND quote_text=$q$Whether it's paving roads in Windham or improving transit planning in Westbrook, this work plan helps strengthen the connections our families, businesses and towns rely on every day.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '4eda22f0-a6db-485b-9d76-e76cf7a9a716','abortion',$q$I will continue standing up for the people of my district and across Maine to protect their well-being and ensuring government does not interfere with these highly personal medical decisions.$q$,$q$I will continue standing up for the people of [my community] and across Maine to protect their well-being and ensuring government does not interfere with these highly personal medical decisions.$q$,'https://www.mainesenate.org/sen-duson-scores-100-on-reproductive-rights-voting-record-in-132nd-legislature/','Maine Senate Democrats',true,$q$From Duson's June 24, 2026 press release on her 100% Planned Parenthood Maine Action Fund scorecard; verbatim except 'my district' bracketed to '[my community]' to remove the office-holder identifier. Shows her framing abortion as a personal medical decision government should not restrict, matching the most permissive stance.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='4eda22f0-a6db-485b-9d76-e76cf7a9a716' AND topic_key='abortion' AND quote_text=$q$I will continue standing up for the people of my district and across Maine to protect their well-being and ensuring government does not interfere with these highly personal medical decisions.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '4eda22f0-a6db-485b-9d76-e76cf7a9a716','civil-rights',$q$LD 2176 is a bill to support renters of every background, especially our immigrant community. It ensures that personal information remains personal. It clarifies that there is no room for intimidation and retaliation in our housing system. Everyone deserves a safe and private place to call home.$q$,$q$[This bill] is a bill to support renters of every background, especially our immigrant community. It ensures that personal information remains personal. It clarifies that there is no room for intimidation and retaliation in our housing system. Everyone deserves a safe and private place to call home.$q$,'https://www.mainesenate.org/sen-duson-introduces-bill-to-bolster-privacy-of-maine-tenants-protect-against-retaliation/','Maine Senate Democrats',true,$q$From Duson's March 16, 2026 press release introducing LD 2176; verbatim except the bill number 'LD 2176' bracketed to '[This bill]' to avoid identifying the sponsor via the bill's public sponsorship record. Shows her framing the bill as strengthening legal protections for a vulnerable population, matching a civil-rights-enforcement stance.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='4eda22f0-a6db-485b-9d76-e76cf7a9a716' AND topic_key='civil-rights' AND quote_text=$q$LD 2176 is a bill to support renters of every background, especially our immigrant community. It ensures that personal information remains personal. It clarifies that there is no room for intimidation and retaliation in our housing system. Everyone deserves a safe and private place to call home.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'ab357826-a155-4d8a-872f-de865129a256','abortion',$q$My work for reproductive health started before serving in the Legislature and it is not something I will stop fighting for.$q$,$q$My work for reproductive health started before serving in the Legislature and it is not something I will stop fighting for.$q$,'https://www.mainesenate.org/sen-talbot-ross-scores-100-on-reproductive-rights-voting-record-in-132nd-legislature/','Maine Senate Democrats',true,$q$Verbatim from Talbot Ross's own official Senate press release (June 2026) on her Planned Parenthood scorecard. No edits needed — the quote contains no name, office, or party references that would identify the speaker.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='ab357826-a155-4d8a-872f-de865129a256' AND topic_key='abortion' AND quote_text=$q$My work for reproductive health started before serving in the Legislature and it is not something I will stop fighting for.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'ab357826-a155-4d8a-872f-de865129a256','civil-rights',$q$This is not just a matter of reorganizing state government for the sake of expansion or improved functioning. This is a moment in which we can uphold our promise to Mainers now and in the future that we will do everything in our power to protect their rights as Americans and Mainers and to ensure that justice is done.$q$,$q$This is not just a matter of reorganizing state government for the sake of expansion or improved functioning. This is a moment in which we can uphold our promise to Mainers now and in the future that we will do everything in our power to protect their rights as Americans and Mainers and to ensure that justice is done.$q$,'https://mainemorningstar.com/2024/02/22/seeking-full-enforcement-of-maine-civil-rights-act-talbot-ross-proposes-new-unit-in-ags-office/','Maine Morning Star',true,$q$Verbatim from Maine Morning Star's Feb. 2024 coverage of her civil-rights-enforcement-unit bill; no edits made — no name, office, or party reference present. Shows her forward-looking rationale for strengthening civil rights enforcement, matching stance 2 on this topic.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='ab357826-a155-4d8a-872f-de865129a256' AND topic_key='civil-rights' AND quote_text=$q$This is not just a matter of reorganizing state government for the sake of expansion or improved functioning. This is a moment in which we can uphold our promise to Mainers now and in the future that we will do everything in our power to protect their rights as Americans and Mainers and to ensure that justice is done.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'ab357826-a155-4d8a-872f-de865129a256','homelessness',$q$Maine needs sustained, long-term investments in shelter and housing to truly meet the need.$q$,$q$Maine needs sustained, long-term investments in shelter and housing to truly meet the need.$q$,'https://www.mainesenate.org/new-law-to-stabilize-emergency-shelter-funding-takes-effect/','Maine Senate Democrats',true,$q$Verbatim from her official Senate press release marking LD 698 taking effect (Oct. 2025); no edits needed since no name, office, or party is present. Captures her forward call for continued shelter investment, aligning with stance 2's emphasis on shelter capacity and outreach services.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='ab357826-a155-4d8a-872f-de865129a256' AND topic_key='homelessness' AND quote_text=$q$Maine needs sustained, long-term investments in shelter and housing to truly meet the need.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT 'ab357826-a155-4d8a-872f-de865129a256','judicial-criminal-justice',$q$This bill, if signed by Gov. Mills, will be a step in the right direction in recognizing Mainers who have paid their debt to society and wish to claim their lives back without fear of being penalized for life.$q$,$q$This bill, if signed by [the governor], will be a step in the right direction in recognizing Mainers who have paid their debt to society and wish to claim their lives back without fear of being penalized for life.$q$,'https://www.mainesenate.org/maine-legislature-passes-sen-talbot-ross-bill-to-seal-criminal-history-record-information-for-low-level-offenses/','Maine Senate Democrats',true,$q$Verbatim from her official Senate press release on LD 1911 (2026); replaced the named governor with '[the governor]' to remove the only identifying reference. Directly expresses her rehabilitative rationale, matching stance 1.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='ab357826-a155-4d8a-872f-de865129a256' AND topic_key='judicial-criminal-justice' AND quote_text=$q$This bill, if signed by Gov. Mills, will be a step in the right direction in recognizing Mainers who have paid their debt to society and wish to claim their lives back without fear of being penalized for life.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '0b0e2f33-d54b-486b-abe8-70c30b7c33eb','abortion',$q$The health of our communities hinges on protected access to these essential care services and robust support for the organizations that make reproductive healthcare affordable to all in our state.$q$,$q$The health of our communities hinges on protected access to these essential care services and robust support for the organizations that make reproductive healthcare affordable to all in our state.$q$,'https://www.mainesenate.org/sen-carney-scores-100-on-reproductive-rights-voting-record-in-132nd-legislature/','Maine Senate Democrats',true,$q$Verbatim from her official Senate press release on the 2026 Planned Parenthood scorecard; no edits needed as the excerpt contains no name, office, or party reference. Reflects her forward-looking support for accessible, funded reproductive healthcare, matching stance 1.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='0b0e2f33-d54b-486b-abe8-70c30b7c33eb' AND topic_key='abortion' AND quote_text=$q$The health of our communities hinges on protected access to these essential care services and robust support for the organizations that make reproductive healthcare affordable to all in our state.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '0b0e2f33-d54b-486b-abe8-70c30b7c33eb','judicial-access-to-justice',$q$This emergency investment will protect all defendants' constitutional right to legal representation – because access to justice should not be contingent on one's ability to pay.$q$,$q$This emergency investment will protect all defendants' constitutional right to legal representation – because access to justice should not be contingent on one's ability to pay.$q$,'https://www.mainesenate.org/governor-signs-sen-carney-bill-to-fund-public-defense-services-protect-constitutional-rights/','Maine Senate Democrats',true,$q$Verbatim from her official Senate press release on LD 2059 (2026); no edits needed, no identifying references present. Directly states her view that court access shouldn't depend on wealth, matching stance 1.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='0b0e2f33-d54b-486b-abe8-70c30b7c33eb' AND topic_key='judicial-access-to-justice' AND quote_text=$q$This emergency investment will protect all defendants' constitutional right to legal representation – because access to justice should not be contingent on one's ability to pay.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '0d01124b-78df-448b-b34a-28f10b39ba8c','abortion',$q$As federal officials fight to erode access to healthcare, reproductive and otherwise, Maine remains a place where all patients can receive the care they need.$q$,$q$As federal officials fight to erode access to healthcare, reproductive and otherwise, Maine remains a place where all patients can receive the care they need.$q$,'https://www.mainesenate.org/sen-brenner-scores-100-on-reproductive-rights-voting-record-in-132nd-legislature/','Maine Senate Democrats',true,$q$Verbatim from her official Senate press release on the 2026 Planned Parenthood scorecard; no edits needed, no name/office/party present. A forward-looking declarative statement defending continued state-level reproductive healthcare access, matching stance 1.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='0d01124b-78df-448b-b34a-28f10b39ba8c' AND topic_key='abortion' AND quote_text=$q$As federal officials fight to erode access to healthcare, reproductive and otherwise, Maine remains a place where all patients can receive the care they need.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '0d01124b-78df-448b-b34a-28f10b39ba8c','climate-change',$q$The passage of this bill lays the groundwork for a future climate superfund, which would ease the financial burden Maine communities are currently shouldering alone by asking leading polluters to pay their fair share of the bill.$q$,$q$The passage of this bill lays the groundwork for a future climate superfund, which would ease the financial burden Maine communities are currently shouldering alone by asking leading polluters to pay their fair share of the bill.$q$,'https://www.mainesenate.org/sen-brenner-bill-to-develop-a-climate-superfund-signed-into-law/','Maine Senate Democrats',true,$q$Verbatim from her official Senate press release on LD 1870 being signed into law (April 2026); no edits needed, no identifying references present. Explains her rationale for the polluter-pays climate superfund, matching stance 3.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='0d01124b-78df-448b-b34a-28f10b39ba8c' AND topic_key='climate-change' AND quote_text=$q$The passage of this bill lays the groundwork for a future climate superfund, which would ease the financial burden Maine communities are currently shouldering alone by asking leading polluters to pay their fair share of the bill.$q$);
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at) SELECT '4248ed15-3a23-47e7-a24d-6235379b8e43','taxes',$q$Maine cannot tax and spend its way into affordability. After years of record budgets, new taxes and declining outcomes, it is time for Augusta to take a different approach.$q$,$q$Maine cannot tax and spend its way into affordability. After years of record budgets, new taxes and declining outcomes, it is time for [the state government] to take a different approach.$q$,'https://mesenategop.com/2026/05/19/maine-cannot-tax-and-spend-its-way-to-affordability/','Maine Senate Republicans',true,$q$Verbatim quote from Harrington's own May 2026 column arguing against further tax increases and for a different fiscal approach, which supports a taxes value of 4 (cut taxes, scale back spending growth). Edited only to replace 'Augusta' (Maine's capitol, an identifying place name) with a neutral phrase.$q$,now(),now() WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='4248ed15-3a23-47e7-a24d-6235379b8e43' AND topic_key='taxes' AND quote_text=$q$Maine cannot tax and spend its way into affordability. After years of record budgets, new taxes and declining outcomes, it is time for Augusta to take a different approach.$q$);
